import ImageGallery from "react-image-gallery";
import "react-image-gallery/styles/css/image-gallery.css";
import { images } from "./dataMainPage";
import Logo from "./Logo.png";

export const MainPage = () => {
  return (
    <div className="root-style">
      <header className="header bg-primary-gradiant">
        <a
          href="#"
          className="head-nav-item-logo text-decoration-none text-white"
        >
          <img src={Logo} alt="OdinSchool" height="45" width="190" />
        </a>
        <div className="content-header">
          <a href="#" className="text-decoration-none text-white ">
            Герман Екатерина, 2015gev@gmail.com
          </a>
        </div>
      </header>
      <div className="wrapper">
        <ImageGallery items={images} />
      </div>
      <footer className="footer bg-primary-gradiant">
        © 2024 Все права защищены.
      </footer>
    </div>
  );
};
