import Markdown from "markdown-to-jsx";
import { useEffect, useState } from "react";
import "./styles/code.css";
import "./styles/post.css";

//import Code from "./code.js";
import { CopyToClipboard } from "react-copy-to-clipboard";
import { PrismLight as SyntaxHighlighter } from "react-syntax-highlighter";
import jsx from "react-syntax-highlighter/dist/esm/languages/prism/jsx";
import {
  materialDark,
  materialLight,
} from "react-syntax-highlighter/dist/esm/styles/prism";

import { CopyIcon, MoonIcon, PasteIcon, SunIcon } from "../../../assets/icons";
import { MmdCode } from "../mermaid/mermaidCode";

function Code({ children, language, isDark, setIsDark }) {
  const [isCopied, setIsCopied] = useState(false);
  SyntaxHighlighter.registerLanguage("jsx", jsx);

  const setCopied = () => {
    setIsCopied(true);
    setTimeout(() => {
      setIsCopied(false);
    }, 1000);
  };

  return (
    <div className="code">
      <div className="code__icons">
        <button onClick={() => setIsDark(!isDark)}>
          {isDark ? <MoonIcon /> : <SunIcon />}
        </button>

        <CopyToClipboard text={children}>
          <button onClick={() => setCopied()}>
            {isCopied ? (
              <span title="Copied!">
                <PasteIcon />
              </span>
            ) : (
              <span title="Copy to Clipboard">
                <CopyIcon />
              </span>
            )}
          </button>
        </CopyToClipboard>
      </div>

      <SyntaxHighlighter
        language={language}
        style={isDark ? materialDark : materialLight}
      >
        {children}
      </SyntaxHighlighter>
    </div>
  );
}

const Post = (props) => {
  const { name } = props;
  const [postContent, setPostcontent] = useState("");
  const [isDark, setIsDark] = useState(true);

  useEffect(() => {
    import(`../${name}.md`).then((res) =>
      fetch(res.default)
        .then((response) => response.text())
        .then((response) => setPostcontent(response))
        .catch((err) => console.log(err))
    );
  }, [name]);

  return (
    <div className="article__wrapper">
      <article>
        <main>
          <Markdown
            options={{
              overrides: {
                Code: {
                  component: Code,
                  props: {
                    isDark,
                    setIsDark,
                  },
                },
                MmdCode: {
                  component: MmdCode,
                },
              },
            }}
          >
            {postContent}
          </Markdown>
        </main>
      </article>
    </div>
  );
};

export default Post;
