import mermaid from "mermaid";
import { useEffect, useState } from "react";
import "./styles.css";

//const Similarity = "60%";

mermaid.initialize({
  startOnLoad: true,
});

export const MermaidChart = (props) => {
  useEffect(() => {
    mermaid.contentLoaded();
  }, []);
  return <div className="mermaid">{props.chart}</div>;
};
export const keywords = [
  "learning1",
  "data visualization",
  "machine learning",
  "analytics",
];

export const MmdCode = (props) => {
  console.log(props);
  const { children, heading } = props;
  console.log(children);
  const [state, setState] = useState({
    keywords: [],
    keyphrases: [],
  });

  useEffect(() => {
    setState({
      keywords: [],
      keyphrases: [],
    });
    generateData();
  }, []);

  let generateData = () => {
    let data = {
      keywords: [],
      keyphrases: [],
    };
    keywords.forEach((kwrd) => {
      if (kwrd.indexOf(" ") >= 0) {
        data.keyphrases.push(kwrd);
      } else {
        data.keywords.push(kwrd);
      }
    });
    setState(data);
  };

  return (
    <div>
      <p>{JSON.stringify(state.keyphrases[0])}</p>
      <h1>{heading}</h1>
      {keywords.length ? (
        <>
          {state.keywords.length !== 0 ? (
            <MermaidChart chart={children} />
          ) : (
            <></>
          )}
        </>
      ) : (
        <></>
      )}
    </div>
  );
};
