import { Box, Typography } from "@mui/material";

export const styleBoxMain = {
  textAlign: "center",
  display: "flex",
  flexDirection: "column",
  alignItems: "center",
  justifyContent: "center",
};
export const styleBoxAdd = {
  height: "80vh",
  display: "flex",
  flexDirection: "row",
  alignItems: "center",
  justifyContent: "center",
};

export const styleTypogh = {
  borderRight: (theme) => `1px solid ${theme.palette.divider}`,
  display: "inline-block",
  margin: 0,
  marginRight: "20px",
  padding: "0 23px 0 0",
  fontSize: "24px",
  fontWeight: 500,
  verticalAlign: "top",
  lineHeight: "49px",
  // fontFamily: "Korinna_Regular",
};

export const styleText = {
  display: "inline-block",
  textAlign: "left",
  lineHeight: "49px",
  height: "49px",
  verticalAlign: "middle",
  // fontFamily: "Korinna_Regular",
};

export const PageDefault = () => {
  return (
    <Box sx={styleBoxMain}>
      <Box sx={styleBoxAdd}>
        <Typography sx={styleTypogh}>404</Typography>
        <Typography sx={styleText}>СТРАНИЦА НЕ НАЙДЕНА.</Typography>
      </Box>
    </Box>
  );
};
