import { ThemeProvider } from "@mui/material/styles";
import { createContext, useMemo, useState } from "react";
import {
  HashRouter as Router,
  //BrowserRouter as Router,
  Route,
  Routes,
} from "react-router-dom";
import "./App.css";
import { MainPage } from "./pages/mainPage/main_page";
import { PageManualPython } from "./pages/manualPython/manualPagePython";
import { PageDefault } from "./pages/pageDefault";
import { getAppTheme } from "./styles/styleProfile";

export const DARK_MODE_THEME = "dark";
export const LIGHT_MODE_THEME = "light";

function App() {
  // const location = useLocation();
  // const background = location.state && location.state.background;
  const ThemeModeContext = createContext("Default");
  const [mode, setMode] = useState(LIGHT_MODE_THEME);

  const themeMode = useMemo(
    () => ({
      toggleThemeMode: () => {
        setMode((prevMode) =>
          prevMode === LIGHT_MODE_THEME ? DARK_MODE_THEME : LIGHT_MODE_THEME
        );
      },
    }),
    []
  );

  const [theme, setTheme] = useState(
    useMemo(() => getAppTheme(mode, "Default"), [mode])
  );

  return (
    <ThemeModeContext.Provider value={"light"}>
      <ThemeProvider theme={theme}>
        <Router>
          <Routes>
            <Route path="/" element={<MainPage />} />;
            <Route key="page404" path="*" element={<PageDefault />} />;
            <Route path="/python" element={<PageManualPython />} />;
          </Routes>
        </Router>
      </ThemeProvider>
    </ThemeModeContext.Provider>
  );
}

export default App;
