import { createTheme, responsiveFontSizes } from "@mui/material";

import {
  themeDefault,
  themeDevExpress,
  themeGreen,
  themeOffice2007Gray,
  themeOffice2007GrayGradient,
  themeOffice2007Green,
  themeOffice2007GreenGradient,
  themeOfficeDevExpressGradient,
} from "./dataStyleProfile";

let TOOLTIP_HEADER_COLOR = "#6a6a6a";
const BORDER_RADIUS_COMPONENT = "0.3em";

// Стиль кнопки с текстом
export const styleButtonText = {
  color: (theme) => theme.palette.secondary.light,
  background: (theme) => theme.palette.secondary.main,
  ":hover": {
    backgroundColor: (theme) => theme.palette.warning.light,
  },
};

// Заливка градиентом и настройка текста

export const styleGradientHorBackground = {
  background:
    window.localStorage.gradient === "yes"
      ? window.localStorage.gradient_main
      : (theme) => theme.palette.primary.main,
};

export const styleGradientHor = Object.assign({}, styleGradientHorBackground, {
  color: (theme) => theme.palette.primary.contrastText,
});

export const styleGradientText = {
  color:
    window.localStorage.gradient === "yes"
      ? (theme) => theme.palette.primary.contrastText
      : (theme) => theme.palette.secondary.light,
};

export const styleGradientVert = Object.assign({}, styleGradientText, {
  background:
    window.localStorage.gradient === "yes"
      ? window.localStorage.gradient_add
      : (theme) => theme.palette.primary.main,
});

export const styleGradientHorMod = Object.assign(
  {},
  styleGradientHorBackground,
  styleGradientText
);

export const styleBorder = (theme) => `1px solid ${theme.palette.divider}`;

export const styleBorderRadiusRight = `${BORDER_RADIUS_COMPONENT} 0 0 ${BORDER_RADIUS_COMPONENT}`;

export const styleBorderRaduisRightFirst = `${BORDER_RADIUS_COMPONENT} 0 0 0`;

// Сборка градиентов цветовых профилей
export const AppGradientThemeColor = (theme) => {
  switch (theme) {
    case "Green":
      window.localStorage.gradient = undefined;
      return themeGreen;
    case "OfficeGreen":
      window.localStorage.gradient = "yes";
      return GradientTheme(
        themeOffice2007GreenGradient[0],
        themeOffice2007GreenGradient[1],
        themeOffice2007GreenGradient[2]
      );
    case "OfficeGray":
      window.localStorage.gradient = "yes";
      return GradientTheme(
        themeOffice2007GrayGradient[0],
        themeOffice2007GrayGradient[1],
        themeOffice2007GrayGradient[2]
      );
    case "DevExpress":
      window.localStorage.gradient = "yes";
      return GradientTheme(
        themeOfficeDevExpressGradient[0],
        themeOfficeDevExpressGradient[1],
        themeOfficeDevExpressGradient[2]
      );
    default:
      window.localStorage.gradient = undefined;
      return null;
  }
};

// Сборка цветовых профилей
export const AppThemeColor = (theme) => {
  switch (theme) {
    case "Green":
      return themeGreen;
    case "OfficeGreen":
      return themeOffice2007Green;
    case "OfficeGray":
      return themeOffice2007Gray;
    case "DevExpress":
      return themeDevExpress;
    default:
      return themeDefault;
  }
};

export const GradientTheme = (color1, color2, color3) => {
  window.localStorage.gradient = "yes";
  window.localStorage.gradient_main = `linear-gradient(0deg, ${color1} 27%, ${color2} 72%, ${color3} 100%)`;
  window.localStorage.gradient_add = `linear-gradient(90deg, ${color1} 27%, ${color2} 72%, ${color3} 100%)`;
};

// Настройка Theme
export const getAppTheme = (mode, colorTheme) => {
  let themeApp;

  AppThemeColor(colorTheme).map(
    (theme) =>
      (themeApp = createTheme({
        components: {
          MuiSwitch: {
            switch: {
              styleOverrides: {
                root: {
                  color: (theme) => theme.palette.secondary.main,
                },
              },
            },
          },
          MuiTooltip: {
            styleOverrides: {
              tooltip: {
                fontSize: "1.2em !important",
                color: (theme) => theme.palette.primary.contrastText,
                backgroundColor: TOOLTIP_HEADER_COLOR,
                border: (theme) => `1px solid ${theme.palette.divider}`,
                marginLeft: "0.5em !important",
                marginRight: "0.5em !important",
                marginTop: "0.5em !important",
                marginBottom: "0.5em !important",

                fontFamily: "Arial",
                letterSpacing: "0.05em",
              },
            },
          },
          MuiTypography: {
            styleOverrides: {
              root: {
                fontSize: "1em",
                fontFamily: "Arial",
              },
            },
          },
          MuiTableCell: {
            styleOverrides: {
              root: {
                fontSize: "1em",

                fontFamily: "Arial",
              },
            },
          },
          MuiTab: {
            styleOverrides: {
              root: {
                fontFamily: "Arial",
              },
            },
          },
          MuiTablePagination: {
            styleOverrides: {
              root: {
                fontFamily: "Arial",
              },
            },
          },

          MuiLink: {
            styleOverrides: {
              root: {
                ":hover": {
                  backgroundColor: (theme) => theme.palette.warning.light,
                },
              },
            },
          },

          MuiDataGrid: {
            styleOverrides: {
              selectLabel: {
                fontFamily: "Arial",
              },

              root: {
                fontFamily: "Arial",
              },
            },
          },
        },
        palette: {
          primary: {
            main: theme.MAIN_COLOR,
            light: theme.MAIN_ADD_COLOR,
            dark: theme.MAIN_COMPONENT_COLOR,
            contrastText: theme.TEXT_COLOR,
          },
          divider: theme.BORDER_COLOR,

          secondary: {
            main: theme.ACTIVE_COLOR_COMPONENT,
            light: theme.ACTIVE_COLOR,
            dark: theme.SELECT_COLOR_COMPONENT,
          },
          warning: {
            main: theme.HOVER_CLICK_COLOR_COMPONENT,
            light: theme.HOVER_COLOR_COMPONENT,
            dark: theme.HOVER_COLOR_TEXT,
          },
          mode,
        },
      }))
  );
  themeApp = responsiveFontSizes(themeApp);
  return themeApp;
};
